import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_basic():
    assert conversion_rate([{"converted": True}, {"converted": False}]) == 0.5


def test_pooled_conversion_rate_equal_groups():
    groups = {"a": [{"converted": True}, {"converted": False}], "b": [{"converted": True}, {"converted": False}]}
    assert pooled_conversion_rate(groups) == 0.5


def test_parse_session_log_one_line():
    assert parse_session_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "converted": True}]


def test_campaign_summary_basic():
    e = [{"id": "a", "day": 1, "converted": True}, {"id": "b", "day": 2, "converted": False}]
    assert campaign_summary({"g": e}, 1)["groups"] == 1


def test_conversion_rate_counts_none_in_denominator():
    events = [{"converted": True}, {"converted": None}, {"converted": False}]
    assert conversion_rate(events) == 1 / 3


def test_conversion_rate_empty():
    assert conversion_rate([]) == 0.0


def test_pooled_conversion_rate_weights_sessions_not_groups():
    groups = {
        "small": [{"converted": True}],
        "large": [{"converted": False}, {"converted": None}, {"converted": False}],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({"empty": []}) == 0.0
    assert pooled_conversion_rate({}) == 0.0


@pytest.mark.parametrize(("days", "expected"), [(0, 0), (2, 12), (5, 14)])
def test_conversions_in_window(days, expected):
    assert conversions_in_window([2, 5, 7], days) == expected


def test_parse_session_log_flags_and_skipped_lines():
    lines = ["", " \t\n", "  # comment,with,commas", " a , 2 , 1 ", "b, 3, 0", "c,4,  "]
    assert parse_session_log(lines) == [
        {"id": "a", "day": 2, "converted": True},
        {"id": "b", "day": 3, "converted": False},
        {"id": "c", "day": 4, "converted": None},
    ]


@pytest.mark.parametrize("bad_line", ["b,2", "b,2,1,extra", "b,not-an-integer,1"])
def test_parse_session_log_reports_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_session_log([" # header", "  ", "a,1,1", bad_line])


def test_dedupe_sessions_keeps_last_record_and_sorts_by_day_then_id():
    superseded = {"id": "b", "day": 5, "converted": True}
    latest = {"id": "b", "day": 2, "converted": False}
    same_day = {"id": "a", "day": 2, "converted": True}
    earlier_day = {"id": "z", "day": 1, "converted": None}
    assert dedupe_sessions([superseded, same_day, latest, earlier_day]) == [
        earlier_day, same_day, latest
    ]


def test_daily_conversion_counts_includes_both_endpoints_and_fills_gaps():
    events = parse_session_log(["a,0,1", "b,1,1", "c,1,1", "d,2,0", "e,2,", "f,3,1", "g,4,1"])
    assert daily_conversion_counts(events, 1, 3) == [2, 0, 1]
    assert daily_conversion_counts(events, 3, 1) == []


def test_campaign_summary_uses_calendar_days_and_ignores_empty_groups():
    groups = {"a": parse_session_log(["a,1,1"]), "b": parse_session_log(["b,4,0", "c,5,"]), "empty": []}
    assert campaign_summary(groups, 2) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert campaign_summary(groups, 5) == {"rate": 0.333, "recent": 1, "groups": 2}
    assert campaign_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_converting_groups_excludes_empty_groups_and_breaks_ties_by_name():
    groups = {
        "z": [{"converted": True}],
        "empty": [],
        "a": [{"converted": True}],
        "b": [{"converted": False}],
    }
    assert top_converting_groups(groups, 1) == ["a"]
    assert top_converting_groups(groups, 5) == ["a", "z", "b"]


def test_conversion_rate_by_group_sorts_names_and_distinguishes_empty_groups():
    groups = {"z": [], "b": [{"converted": False}], "a": [{"converted": True}]}
    assert list(conversion_rate_by_group(groups).items()) == [("a", 1.0), ("b", 0.0), ("z", None)]


@pytest.mark.parametrize(("counts", "expected"), [([], 0), ([0, -1], 0), ([1, 2, 0, 3, -1, 4, 5], 2)])
def test_longest_conversion_streak(counts, expected):
    assert longest_conversion_streak(counts) == expected

